llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, a hydroxyethylamine HIV protease inhibitor with a tert-butylamide and similar transition-state isostere, has systemic bioavailability of about 60% in humans, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "KNI-272, a peptidomimetic HIV protease inhibitor sharing the tert-butylamide and hydrophobic P1/P2 features, showed absolute oral bioavailability of about 55% in adult patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Boceprevir, a peptidomimetic protease inhibitor with a fused bicyclic proline surrogate and tert-butylamide, has approximately 20% oral bioavailability in humans, at the threshold and supportive of high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Remikiren, a more highly peptidic renin inhibitor, had very low absolute oral bioavailability of 0.2% in humans, providing a low-bioavailability counterexample; its greater peptide character and different target reduce transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a hydroxyethylamine peptidomimetic with a tert-butylamide and a fused bicyclic amine, most analogous to indinavir and KNI-272, both of which show moderate-to-good human oral bioavailability (≈30–60%). Low-bioavailability analogues such as remikiren and alvimopan are less structurally transferable. Overall, the evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Morgan similarities to evidence molecules are modest (0.21–0.28), limiting quantitative transferability.",
    "Human pharmacokinetic effects of the phenolic group, thioether, and basic bicyclic amine are not directly measured.",
    "KNI-272 showed lower bioavailability in children (12%), introducing age/formulation uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

